ListNode MergeTwo(ListNode a, ListNode b) {
    var dummy = new ListNode();          // dummy head: there is always a tail
    var tail = dummy;
    while (a != null && b != null) {
        if (a.val <= b.val) { tail.next = a; a = a.next; }
        else { tail.next = b; b = b.next; }
        tail = tail.next;
    }
    tail.next = a ?? b;                  // the rest of one of the lists
    return dummy.next;
}
