public sealed class FrameStats : MonoBehaviour {
    const int N = 120;                                   // about 2 seconds at 60 FPS
    readonly float[] ring = new float[N], scratch = new float[N];
    int head, count;

    void Update() {
        ring[head] = Time.unscaledDeltaTime * 1000f;     // ms
        head = (head + 1) % N;
        if (count < N) count++;
    }

    public float Percentile(float p) {                   // 0.5 is the median, 0.99 is p99
        if (count == 0) return 0f;
        Array.Copy(ring, scratch, count);
        Array.Sort(scratch, 0, count);                   // 120 numbers: a few microseconds
        return scratch[(int)(p * (count - 1))];
    }
}
